import React, { useEffect, useRef, memo } from 'react';
import './NiftyChart.css';

const NiftyChart = () => {
  // We use a specific ID for the container so TradingView knows exactly where to go
  const containerId = 'tv_chart_container';
  const hasLoaded = useRef(false);

  useEffect(() => {
    // Prevent strict-mode double loading
    if (hasLoaded.current) return;
    hasLoaded.current = true;

    // 1. Create the script to load the TradingView library
    const script = document.createElement('script');
    script.src = 'https://s3.tradingview.com/tv.js';
    script.async = true;

    // 2. ONLY build the chart AFTER the library has safely finished loading
    script.onload = () => {
      if (typeof window.TradingView !== 'undefined') {
        new window.TradingView.widget({
          "autosize": true,
          "symbol": "BSE:SENSEX",
          "interval": "D",
          "timezone": "Asia/Kolkata",
          "theme": "light",
          "style": "1", // 1 = Candlesticks
          "locale": "in",
          "enable_publishing": false,
          "backgroundColor": "#ffffff",
          "gridColor": "rgba(20, 196, 181, 0.1)", // Your custom teal
          "hide_legend": false,
          "save_image": false,
          "container_id": containerId // Targets the div below
        });
      }
    };

    // 3. Add the script to the page
    document.getElementById(containerId).appendChild(script);

  }, []);

  return (
    <div className="chart-widget-block advanced-chart-block">
      <h3 className="chart-title">Market Analysis: BSE SENSEX</h3>

      {/* This is the target container for the tv.js library */}
      <div id={containerId} style={{ height: '100%', width: '100%' }}></div>

    </div>
  );
};

export default memo(NiftyChart);
